(def ^:private base
  (delay (let [loaded (checkpoint/load-checkpoint main/default-checkpoint)]
           (assert (= :replayed (:status loaded)) "default checkpoint did not replay")
           (:environment loaded))))

(def ^:private classical
  "The theorems that are classical by design, and the named axioms each one rests on. Every other
  theorem must be axiom-free."
  '{set/finite-of-subsingleton #{logic/excluded-middle} set/finite-or-infinite #{logic/excluded-middle}
    set/infinite-nonempty #{logic/excluded-middle} set/infinite-nontrivial #{logic/excluded-middle}
    set/infinite-or-finite #{logic/excluded-middle} set/not-infinite-equivalence #{logic/excluded-middle}
    set/infinite-union-equivalence #{logic/excluded-middle}
    set/finite-singleton-proposition-equality #{logic/proposition-extensionality}})

(defn- rechecks [ns-sym]
  (let [{:keys [error theorems bundle?]} (main/verify-namespace @base ns-sym)
        env (delay ((ns-resolve ns-sym 'extend-environment) @base))]
    (is (nil? error) (str ns-sym ": " error))
    (is (or bundle? (seq theorems)) (str ns-sym " names no theorems"))
